function cn(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(' '); }
function money(value: number | string) { return naira.format(Number(value) || 0); }

function Mark({ light = false }: { light?: boolean }) {
  return <Link href="/" className={cn('flex items-center gap-3 group', light && 'text-[#f8f1e4]')} data-testid="link-brand-home">
    <img src={brandLogo} alt="BobTech Furnitures" className="size-11 rounded-xl object-cover transition-transform group-hover:rotate-2" />
    <span className="text-[17px] font-semibold tracking-[-.04em]">BobTech <span className={light ? 'text-[#dcae59]' : 'text-accent'}>Furnitures</span></span>
  </Link>;
}

function Button({ children, variant = 'primary', className, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'quiet' | 'outline' | 'coral' }) {
  return <button {...props} className={cn('inline-flex min-h-11 items-center justify-center gap-2 rounded-full px-5 text-sm font-semibold transition-all duration-300 active:scale-[.97] disabled:cursor-not-allowed disabled:opacity-50', variant === 'primary' && 'bg-primary text-primary-foreground hover:-translate-y-0.5 hover:shadow-lift', variant === 'coral' && 'bg-accent text-accent-foreground hover:-translate-y-0.5 hover:shadow-lift', variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/40 hover:bg-muted', variant === 'quiet' && 'text-muted-foreground hover:bg-muted hover:text-foreground', className)} />;
}

