function MarketplaceEdit() {
  const listings = [
    { name: 'The Sapele Lounge Chair', maker: 'Adebayo Woodcraft · Lagos', price: 185000, image: '/images/studio.jpg', tag: 'Hand-finished' },
    { name: 'Nubian Oak Dining Set', maker: 'Ilé Living · Abuja', price: 920000, image: '/images/dining-room.jpg', tag: 'Made to order' },
    { name: 'The Quiet Hour Bed', maker: 'Atrium Objects · Ibadan', price: 640000, image: '/images/bedroom.jpg', tag: 'New arrival' },
    { name: 'Aso Oke Accent Cushion', maker: 'Moyo Home · Lagos', price: 38000, image: '/images/living-room.jpg', tag: 'Small batch' },
  ];
  return <section className="mx-auto max-w-[1320px] px-5 py-20 lg:px-8 lg:py-28"><div className="flex flex-wrap items-end justify-between gap-7"><div><SectionLabel>Curated marketplace</SectionLabel><h2 className="font-display max-w-2xl text-5xl leading-[.92] tracking-[-.04em] sm:text-6xl">Pieces with a point<br /><em>of view.</em></h2><p className="mt-5 max-w-md text-sm leading-6 text-muted-foreground">A considered edit of furniture and objects from makers we would happily put in our own homes.</p></div><Link href="/professionals" className="group flex items-center gap-2 text-sm font-semibold text-primary" data-testid="link-marketplace-explore">Explore the network <ArrowRight size={16} className="transition-transform group-hover:translate-x-1" /></Link></div><div className="mt-10 grid gap-x-5 gap-y-10 sm:grid-cols-2 lg:grid-cols-4">{listings.map((item, i) => <Link href="/professionals" key={item.name} className={cn('group animate-rise', `delay-${Math.min(i + 1, 5)}`)} data-testid={`card-listing-${i}`}><div className="relative aspect-[.82] overflow-hidden rounded-[22px] bg-secondary"><img src={item.image} alt={item.name} className="size-full object-cover transition duration-700 group-hover:scale-105" /><div className="absolute inset-x-3 top-3 flex justify-between"><span className="rounded-full bg-background/90 px-2.5 py-1.5 text-[10px] font-semibold backdrop-blur">{item.tag}</span><span className="grid size-8 place-items-center rounded-full bg-background/85 opacity-0 transition group-hover:opacity-100"><ArrowUpRight size={14} /></span></div></div><div className="mt-4 flex items-start justify-between gap-3"><div><h3 className="font-display text-2xl leading-none">{item.name}</h3><p className="mt-2 text-[11px] text-muted-foreground">{item.maker}</p></div><span className="whitespace-nowrap text-sm font-bold text-primary">{money(item.price)}</span></div></Link>)}</div></section>;
}

function ProviderCard({ provider }: { provider: any }) {
  const profileHref = typeof provider.id === 'number' ? `/professionals/${provider.id}` : '/professionals';
  return <Link href={profileHref} className="group block overflow-hidden rounded-2xl border border-border/80 bg-card shadow-soft transition-all duration-500 hover:-translate-y-1 hover:shadow-lift" data-testid={`card-provider-${provider.id}`}><div className="relative aspect-[1.15] overflow-hidden bg-secondary"><img src={provider.coverImage || imageFallback} alt={`${provider.name} portfolio`} className="size-full object-cover transition duration-700 group-hover:scale-105" onError={(e) => { e.currentTarget.src = imageFallback; }} /><div className="absolute left-4 top-4 flex gap-2">{provider.verified && <span className="flex items-center gap-1 rounded-full bg-primary px-2.5 py-1 text-[10px] font-bold text-primary-foreground"><ShieldCheck size={12} /> Verified</span>}<span className="rounded-full bg-background/85 px-2.5 py-1 text-[10px] font-bold backdrop-blur">{provider.city}</span></div><span className="absolute right-4 top-4 grid size-9 place-items-center rounded-full bg-background/80 opacity-0 backdrop-blur transition group-hover:opacity-100"><Heart size={16} /></span></div><div className="p-5"><div className="flex items-start justify-between gap-3"><div><h3 className="font-display text-2xl leading-none">{provider.name}</h3><p className="mt-2 text-xs text-muted-foreground">{provider.category}</p></div><div className="flex items-center gap-1 text-xs font-bold"><Star size={13} className="fill-accent text-accent" /> {provider.rating?.toFixed?.(1) ?? provider.rating}</div></div><div className="mt-5 flex items-center justify-between border-t border-border pt-4 text-[11px] text-muted-foreground"><span>From {money(provider.startingPrice)}</span><span className="flex items-center gap-1"><Clock3 size={12} /> {provider.responseTime}</span></div></div></Link>;
}

function Professionals() {
  const [search, setSearch] = useState(''); const [city, setCity] = useState(''); const [category, setCategory] = useState('');
  const params = useMemo(() => ({ search: search || undefined, city: city || undefined, category: category || undefined }), [search, city, category]);
  const providers = useListProviders(params, { query: { queryKey: getListProvidersQueryKey(params), staleTime: 30_000 } });
  return <PageShell><Header /><main className="mx-auto max-w-[1320px] px-5 py-14 lg:px-8 lg:py-20"><PageTitle eyebrow="The directory" title={<>People who know<br /><em>how to make a room sing.</em></>} copy="Trusted interior designers, makers and furniture studios across Nigeria. Search by the kind of feeling you want to come home to." /><div className="mt-12 rounded-2xl border border-border bg-card p-3 shadow-soft"><div className="grid gap-3 md:grid-cols-[1.5fr_1fr_1fr_auto]"><label className="flex h-12 items-center gap-3 rounded-xl bg-muted px-4"><Search size={18} className="text-muted-foreground" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search a name, style or service" className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground" data-testid="input-search-providers" /></label><select value={city} onChange={e => setCity(e.target.value)} className="h-12 rounded-xl bg-muted px-4 text-sm outline-none" data-testid="select-city"><option value="">All cities</option><option value="Lagos">Lagos</option><option value="Abuja">Abuja</option><option value="Ibadan">Ibadan</option><option value="Port Harcourt">Port Harcourt</option></select><select value={category} onChange={e => setCategory(e.target.value)} className="h-12 rounded-xl bg-muted px-4 text-sm outline-none" data-testid="select-category"><option value="">All specialties</option><option value="Interior Design">Interior design</option><option value="Furniture Studio">Furniture studio</option><option value="Architecture">Architecture</option></select><Button variant="outline" className="h-12" onClick={() => { setSearch(''); setCity(''); setCategory(''); }} data-testid="button-clear-filters"><Filter size={16} /> Clear</Button></div></div><div className="mt-12 flex items-center justify-between"><p className="text-sm text-muted-foreground">{providers.isLoading ? 'Finding your people…' : `${providers.data?.length ?? 0} professionals to explore`}</p><button className="flex items-center gap-2 text-sm font-semibold" data-testid="button-sort-providers">Recommended <ChevronDown size={15} /></button></div>{providers.isLoading ? <div className="mt-6 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{[1,2,3,4,5,6].map(i => <Skeleton key={i} className="h-[390px]" />)}</div> : providers.isError ? <div className="mt-6"><ErrorState /></div> : providers.data?.length ? <div className="mt-6 grid gap-5 md:grid-cols-2 lg:grid-cols-3">{providers.data.map(p => <ProviderCard key={p.id} provider={p} />)}</div> : <div className="mt-6"><EmptyState icon={Search} title="No exact matches yet." copy="Try a broader search or explore another city. The right maker may be one filter away." action={<Button variant="outline" onClick={() => { setSearch(''); setCity(''); setCategory(''); }} data-testid="button-reset-search">Reset search</Button>} /></div>}</main></PageShell>;
}

function ProviderProfile() {
  const { id } = useParams<{ id: string }>(); const provider = useGetProvider(Number(id), { query: { queryKey: getGetProviderQueryKey(Number(id)) } }); const [saved, setSaved] = useState(false);
  if (provider.isLoading) return <PageShell><Header /><div className="mx-auto max-w-[1320px] px-5 py-16 lg:px-8"><Skeleton className="h-[520px]" /></div></PageShell>;
  if (provider.isError || !provider.data) return <PageShell><Header /><div className="mx-auto max-w-[800px] px-5 py-20"><ErrorState message="This professional profile is unavailable." /></div></PageShell>;
  const p = provider.data;
  return <PageShell><Header /><main><div className="mx-auto max-w-[1320px] px-5 py-8 lg:px-8"><Link href="/professionals" className="inline-flex items-center gap-2 text-sm text-muted-foreground hover:text-primary" data-testid="link-back-professionals"><ChevronLeft size={16} /> Back to professionals</Link><div className="relative mt-6 aspect-[2/1] max-h-[540px] overflow-hidden rounded-[28px] bg-secondary"><img src={p.coverImage || imageFallback} alt={`${p.name} studio`} className="size-full object-cover" onError={(e) => { e.currentTarget.src = imageFallback; }} /><div className="absolute inset-0 bg-gradient-to-t from-primary/70 via-transparent to-transparent" /><div className="absolute bottom-6 left-6 right-6 flex flex-wrap items-end justify-between gap-5 text-primary-foreground sm:bottom-10 sm:left-10 sm:right-10"><div><span className="mb-3 inline-flex items-center gap-1 rounded-full bg-accent px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-accent-foreground"><ShieldCheck size={12} /> Verified professional</span><h1 className="font-display text-5xl leading-none tracking-[-.04em] sm:text-7xl">{p.name}</h1><p className="mt-3 text-sm text-primary-foreground/75">{p.category} · {p.city}, {p.state}</p></div><button type="button" onClick={() => setSaved(!saved)} className="flex size-12 items-center justify-center rounded-full bg-background text-foreground shadow-soft transition hover:scale-105" data-testid="button-save-provider"><Heart size={19} className={saved ? 'fill-accent text-accent' : ''} /></button></div></div><div className="grid gap-12 py-12 lg:grid-cols-[1fr_330px]"><div><div className="flex flex-wrap gap-3 border-b border-border pb-7">{[['Rating', `${p.rating} / 5`], ['Projects', `${p.completedProjects}+`], ['Response', p.responseTime]].map(([l,v]) => <div key={l} className="min-w-[120px] border-r border-border pr-7"><div className="font-mono-app text-[10px] uppercase tracking-wider text-muted-foreground">{l}</div><div className="mt-2 font-display text-3xl">{v}</div></div>)}</div><h2 className="mt-10 font-display text-4xl">A little about the work.</h2><p className="mt-4 max-w-2xl text-base leading-8 text-muted-foreground">{p.description}</p><div className="mt-8 flex flex-wrap gap-2">{(p.styles ?? []).map(style => <span key={style} className="rounded-full bg-secondary px-3 py-2 text-xs font-medium">{style}</span>)}</div><h2 className="mt-14 font-display text-4xl">Selected work.</h2><div className="mt-6 grid grid-cols-2 gap-3 sm:grid-cols-3">{(p.portfolio ?? []).map((img, i) => <img key={img} src={img || imageFallback} alt={`Project ${i + 1}`} className="aspect-square rounded-xl object-cover" onError={(e) => { e.currentTarget.src = imageFallback; }} />)}</div></div><aside className="h-fit rounded-2xl border border-border bg-card p-6 shadow-soft lg:sticky lg:top-28"><div className="font-mono-app text-[10px] uppercase tracking-wider text-accent">Start a conversation</div><h3 className="mt-3 font-display text-3xl">Make something<br /><em>considered.</em></h3><p className="mt-3 text-sm leading-6 text-muted-foreground">Projects with {p.name} begin with a clear brief and a good conversation.</p><div className="my-6 border-t border-border pt-5 text-sm"><div className="flex justify-between"><span className="text-muted-foreground">Projects from</span><strong>{money(p.startingPrice)}</strong></div><div className="mt-3 flex justify-between"><span className="text-muted-foreground">Typical reply</span><strong>{p.responseTime}</strong></div></div><Link href="/dashboard"><Button className="w-full" data-testid="button-start-project">Start a project <ArrowRight size={16} /></Button></Link><p className="mt-3 text-center text-[11px] text-muted-foreground">No commitment. Just a useful first step.</p></aside></div></div></main></PageShell>;
}

function AiDesigner() {
  const [step, setStep] = useState<'upload' | 'options' | 'generating' | 'result'>('upload'); const [image, setImage] = useState(''); const [fileName, setFileName] = useState(''); const [form, setForm] = useState({ roomType: 'Living room', style: 'Warm modern', color: 'Terracotta & cream', budget: '₦1.5m – ₦3m', length: '', width: '', height: '' }); const [result, setResult] = useState<any>(null); const design = useGenerateAiDesign(); const designs = useListAiDesigns({ query: { queryKey: ['/api/ai/designs'] } });
  const onFile = (file?: File) => { if (!file) return; setFileName(file.name); const reader = new FileReader(); reader.onload = () => { setImage(String(reader.result)); setStep('options'); }; reader.readAsDataURL(file); };
  const generate = () => { setStep('generating'); design.mutate({ data: { ...form, originalImage: image, length: form.length ? Number(form.length) : null, width: form.width ? Number(form.width) : null, height: form.height ? Number(form.height) : null } }, { onSuccess: (data) => { setResult(data); setStep('result'); }, onError: () => setStep('options') }); };
  return <PageShell><Header /><main className="mx-auto max-w-[1320px] px-5 py-14 lg:px-8 lg:py-20"><div className="flex flex-wrap items-end justify-between gap-8"><PageTitle eyebrow="Furni intelligence / 01" title={<>See the room<br /><em>before it exists.</em></>} copy="Upload a photo. Choose a direction. Get a concept grounded in Nigerian homes, useful budgets and pieces you can actually source." /><div className="flex items-center gap-2 font-mono-app text-[10px] uppercase tracking-widest text-muted-foreground">{['Upload','Direct','Concept'].map((label, i) => <div key={label} className="flex items-center gap-2"><span className={cn('grid size-7 place-items-center rounded-full border', i <= ['upload','options','result'].indexOf(step) ? 'border-accent bg-accent text-accent-foreground' : 'border-border')}>{i < ['upload','options','result'].indexOf(step) ? <Check size={13} /> : i + 1}</span><span className="hidden sm:inline">{label}</span>{i < 2 && <span className="mx-1 h-px w-5 bg-border" />}</div>)}</div></div><div className="mt-14 grid gap-6 lg:grid-cols-[1.2fr_.8fr]">{step === 'upload' && <div className="animate-rise surface-grid rounded-[28px] border border-border p-5 sm:p-8"><label className="flex min-h-[420px] cursor-pointer flex-col items-center justify-center rounded-[22px] border-2 border-dashed border-primary/25 bg-card p-8 text-center transition hover:border-accent hover:bg-accent/5"><input type="file" accept="image/*" className="sr-only" onChange={e => onFile(e.target.files?.[0])} data-testid="input-room-photo" /><span className="mb-5 grid size-16 place-items-center rounded-2xl bg-secondary text-primary"><ImagePlus size={27} /></span><span className="font-display text-4xl">Bring the room in.</span><span className="mt-3 max-w-xs text-sm leading-6 text-muted-foreground">Drop a room photo here, or browse your camera roll. A clear, well-lit shot gives us more to work with.</span><span className="mt-7 inline-flex h-11 items-center gap-2 rounded-full bg-primary px-5 text-sm font-semibold text-primary-foreground"><Upload size={16} /> Choose photo</span><span className="mt-4 font-mono-app text-[9px] uppercase tracking-widest text-muted-foreground">JPG or PNG · up to 10MB</span></label></div>}{step === 'options' && <div className="animate-rise grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><div className="relative overflow-hidden rounded-[28px] bg-secondary"><img src={image} alt="Uploaded room" className="size-full min-h-[420px] object-cover" /><div className="absolute left-4 top-4 rounded-full bg-background/85 px-3 py-2 text-xs font-semibold backdrop-blur"><FileImage size={13} className="mr-1 inline" /> {fileName}</div><button type="button" onClick={() => { setStep('upload'); setImage(''); }} className="absolute bottom-4 right-4 rounded-full bg-background/85 px-3 py-2 text-xs font-semibold backdrop-blur hover:bg-background" data-testid="button-change-photo">Change photo</button></div><OptionsForm form={form} setForm={setForm} onSubmit={generate} pending={false} /></div>}{step === 'generating' && <div className="animate-fade overflow-hidden rounded-[28px] bg-primary p-5 text-primary-foreground sm:p-8"><div className="relative aspect-[4/3] overflow-hidden rounded-[22px] bg-primary/50"><img src={image} alt="Analysing uploaded room" className="size-full object-cover opacity-50 grayscale" /><div className="animate-scan absolute left-0 right-0 top-0 h-32 bg-gradient-to-b from-transparent via-accent to-transparent opacity-80" /></div><div className="flex flex-wrap items-center justify-between gap-4 pt-7"><div><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">Working on your room</div><h2 className="mt-2 font-display text-4xl">Finding its next life.</h2></div><LoaderCircle className="animate-spin text-accent" size={26} /></div><div className="mt-6 grid gap-2 text-xs text-primary-foreground/60 sm:grid-cols-3"><span className="flex items-center gap-2"><Check size={14} className="text-accent" /> Reading natural light</span><span className="flex items-center gap-2 animate-pulse-soft"><Sparkles size={14} className="text-accent" /> Balancing materials</span><span className="flex items-center gap-2 text-primary-foreground/35"><Clock3 size={14} /> Matching local makers</span></div></div>}{step === 'result' && result && <AiResult design={result} image={image} onReset={() => { setStep('upload'); setResult(null); setImage(''); }} />}{step !== 'generating' && step !== 'result' && <div className="hidden rounded-[28px] bg-[#e8dfce] p-8 lg:block"><div className="font-mono-app text-[10px] uppercase tracking-widest text-primary/50">A small note</div><div className="mt-24 max-w-sm font-display text-4xl leading-none text-primary">Good rooms aren’t filled.<br /><em>They’re edited.</em></div><div className="mt-12 flex items-center gap-2 text-sm text-primary/60"><span className="size-2 rounded-full bg-accent" /> Our AI starts with what you already have.</div></div>}</div>{designs.data?.length ? <section className="mt-20 border-t border-border pt-10"><SectionLabel>Your saved concepts</SectionLabel><div className="grid gap-4 sm:grid-cols-3">{designs.data.slice(0,3).map(d => <div key={d.id} className="rounded-2xl border border-border bg-card p-4"><img src={d.resultImage || imageFallback} alt="Saved room concept" className="aspect-[1.25] w-full rounded-xl object-cover" onError={e => { e.currentTarget.src = imageFallback; }} /><p className="mt-3 font-display text-2xl">{d.style}</p><p className="text-xs text-muted-foreground">{d.roomType} · {d.budget}</p></div>)}</div></section> : null}</main></PageShell>;
}

function OptionsForm({ form, setForm, onSubmit, pending }: { form: any; setForm: (v: any) => void; onSubmit: () => void; pending: boolean }) {
  const update = (key: string, value: string) => setForm((current: any) => ({ ...current, [key]: value }));
  return <div className="rounded-[28px] border border-border bg-card p-6 sm:p-8"><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">02 / Give it a direction</div><h2 className="mt-3 font-display text-4xl leading-none">A few good signals.</h2><div className="mt-8 space-y-6"><Choice label="Room type" value={form.roomType} options={['Living room','Bedroom','Dining room','Home office']} onChange={v => update('roomType', v)} test="room-type" /><Choice label="Design direction" value={form.style} options={['Warm modern','Soft minimal','Afro-contemporary','Eclectic colour']} onChange={v => update('style', v)} test="design-style" /><Choice label="Colour mood" value={form.color} options={['Terracotta & cream','Forest & sand','Ink & brass','Clay & olive']} onChange={v => update('color', v)} test="colour-mood" /><Choice label="Comfortable investment" value={form.budget} options={['₦500k – ₦1.5m','₦1.5m – ₦3m','₦3m – ₦6m','₦6m+']} onChange={v => update('budget', v)} test="design-budget" /><div><label className="text-xs font-semibold">Approximate dimensions <span className="font-normal text-muted-foreground">(optional, metres)</span></label><div className="mt-2 grid grid-cols-3 gap-2">{[['length','Length'],['width','Width'],['height','Height']].map(([key,label]) => <input key={key} type="number" step=".1" placeholder={label} value={form[key]} onChange={e => update(key, e.target.value)} className="h-11 rounded-xl border border-input bg-background px-3 text-sm outline-none focus:border-primary" data-testid={`input-${key}`} />)}</div></div></div><Button className="mt-8 w-full" variant="coral" onClick={onSubmit} disabled={pending} data-testid="button-generate-design"><Sparkles size={16} /> Generate my concept <ArrowRight size={16} /></Button></div>;
}
function Choice({ label, value, options, onChange, test }: { label: string; value: string; options: string[]; onChange: (v: string) => void; test: string }) { return <div><label className="text-xs font-semibold">{label}</label><div className="mt-2 flex flex-wrap gap-2">{options.map(o => <button type="button" key={o} onClick={() => onChange(o)} className={cn('rounded-full border px-3 py-2 text-xs transition', value === o ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-background hover:border-primary/40')} data-testid={`button-${test}-${o.toLowerCase().replaceAll(' ','-')}`}>{o}</button>)}</div></div>; }
function AiResult({ design, image, onReset }: { design: any; image: string; onReset: () => void }) { const create = useCreateProject(); const [created, setCreated] = useState(false); const startProject = () => create.mutate({ data: { name: `${design.style} ${design.roomType}`, roomType: design.roomType, style: design.style, city: 'Lagos', budget: design.budget, notes: design.summary, imageUrl: design.resultImage || image } }, { onSuccess: () => setCreated(true) }); return <div className="animate-rise lg:col-span-2"><div className="grid gap-6 lg:grid-cols-[1.1fr_.9fr]"><div className="relative overflow-hidden rounded-[28px] bg-secondary"><img src={design.resultImage || image} alt="Generated room concept" className="aspect-[4/3] size-full object-cover" onError={e => { e.currentTarget.src = imageFallback; }} /><div className="absolute left-5 top-5 flex items-center gap-2 rounded-full bg-primary px-3 py-2 text-[10px] font-bold uppercase tracking-wider text-primary-foreground"><Sparkles size={13} className="text-accent" /> Your concept</div></div><div className="rounded-[28px] border border-border bg-card p-7 sm:p-10"><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">The direction</div><h2 className="mt-3 font-display text-5xl leading-[.9]">{design.style}<br /><em>{design.roomType}</em></h2><p className="mt-6 text-sm leading-7 text-muted-foreground">{design.summary}</p><div className="mt-7 grid grid-cols-2 gap-3"><div className="rounded-xl bg-secondary p-4"><div className="font-mono-app text-[9px] uppercase tracking-widest text-muted-foreground">Estimated range</div><div className="mt-2 font-display text-2xl">{money(design.estimatedMin)} – {money(design.estimatedMax)}</div></div><div className="rounded-xl bg-secondary p-4"><div className="font-mono-app text-[9px] uppercase tracking-widest text-muted-foreground">Colour mood</div><div className="mt-2 font-display text-2xl">{design.color}</div></div></div><div className="mt-7 flex flex-wrap gap-3">{created ? <div className="flex flex-1 items-center gap-2 rounded-full bg-[#d5e1d7] px-4 text-sm font-semibold text-primary"><Check size={16} /> Brief sent to your workspace</div> : <Button className="flex-1" variant="coral" onClick={startProject} disabled={create.isPending} data-testid="button-turn-into-project"><BriefcaseBusiness size={16} /> {create.isPending ? 'Saving brief…' : 'Turn into a project'}</Button>}<Button variant="outline" onClick={onReset} data-testid="button-start-over">Start over</Button></div></div></div>{design.recommendations?.length ? <div className="mt-8 rounded-2xl border border-border bg-card p-6"><div className="flex items-center justify-between"><h3 className="font-display text-3xl">The considered list.</h3><span className="text-xs text-muted-foreground">Pieces to source</span></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{design.recommendations.map((item: any) => <div key={item.name} className="flex items-center gap-3 rounded-xl bg-muted p-3"><img src={item.image || imageFallback} alt={item.name} className="size-14 rounded-lg object-cover" onError={e => { e.currentTarget.src = imageFallback; }} /><div className="min-w-0"><p className="truncate text-sm font-semibold">{item.name}</p><p className="mt-1 text-xs text-muted-foreground">{money(item.price)} · qty {item.quantity}</p></div></div>)}</div></div> : null}</div>; }

function Dashboard() {
  const summary = useGetDashboardSummary({ query: { queryKey: ['/api/dashboard/summary'] } }); const projects = useListProjects({ query: { queryKey: getListProjectsQueryKey() } }); const [selected, setSelected] = useState<number | null>(null); const project = useGetProject(selected ?? 0, { query: { enabled: !!selected, queryKey: getGetProjectQueryKey(selected ?? 0) } });
  const s = summary.data;
  const metrics: Array<{ label: string; value: string | number; icon: ElementType }> = [
    { label: 'Active projects', value: s?.activeProjects ?? '—', icon: BriefcaseBusiness },
    { label: 'Pending quotes', value: s?.pendingQuotes ?? '—', icon: MessageCircle },
    { label: 'Total invested', value: s ? money(s.totalSpent) : '—', icon: BarChart3 },
    { label: 'Saved makers', value: s?.savedProfessionals ?? '—', icon: Heart },
  ];
  return <WorkspaceShell type="customer"><div className="flex flex-wrap items-end justify-between gap-6"><div><SectionLabel>Your home base</SectionLabel><h1 className="font-display text-5xl leading-none sm:text-6xl">Good morning,<br /><em>Amaka.</em></h1></div><Link href="/ai-room-designer"><Button variant="coral" data-testid="button-dashboard-new-design"><Plus size={17} /> New room concept</Button></Link></div>{summary.isError ? <div className="mt-8"><ErrorState /></div> : <div className="mt-10 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{metrics.map(({ label, value, icon: MetricIcon }, i) => <div key={label} className={cn('rounded-2xl p-5', i === 0 ? 'bg-primary text-primary-foreground' : 'border border-border bg-card')}><MetricIcon size={18} className="text-accent" /><div className="mt-7 font-mono-app text-[10px] uppercase tracking-widest opacity-65">{label}</div><div className="mt-2 font-display text-3xl">{String(value)}</div></div>)}</div>}{selected && project.data ? <div className="mt-8 animate-rise rounded-2xl border border-primary/20 bg-[#d5e1d7] p-6"><div className="flex items-start justify-between"><div><div className="font-mono-app text-[10px] uppercase tracking-widest text-primary/55">Project detail</div><h2 className="mt-2 font-display text-3xl">{project.data.name}</h2><p className="mt-2 text-sm text-primary/65">{project.data.city} · {project.data.budget} · {project.data.providerName || 'Finding your professional'}</p></div><button onClick={() => setSelected(null)} data-testid="button-close-project"><X size={18} /></button></div><div className="mt-6 h-2 overflow-hidden rounded-full bg-primary/10"><div className="h-full rounded-full bg-accent" style={{ width: `${project.data.progress}%` }} /></div><div className="mt-2 flex justify-between text-xs text-primary/60"><span>{project.data.status}</span><span>{project.data.progress}% complete</span></div></div> : null}<div className="mt-14 grid gap-8 lg:grid-cols-[1.3fr_.7fr]"><section><div className="flex items-center justify-between"><h2 className="font-display text-4xl">Your projects</h2><span className="font-mono-app text-[10px] uppercase tracking-widest text-muted-foreground">{projects.data?.length ?? 0} total</span></div><div className="mt-5 space-y-3">{projects.isLoading ? [1,2,3].map(i => <Skeleton key={i} className="h-24" />) : projects.isError ? <ErrorState /> : projects.data?.length ? projects.data.map(p => <button key={p.id} type="button" onClick={() => setSelected(p.id)} className="group flex w-full items-center gap-4 rounded-2xl border border-border bg-card p-4 text-left transition hover:-translate-y-0.5 hover:border-primary/30 hover:shadow-soft" data-testid={`button-project-${p.id}`}><span className="grid size-12 place-items-center rounded-xl bg-secondary text-primary"><HomeIcon size={19} /></span><span className="min-w-0 flex-1"><span className="block truncate font-semibold">{p.name}</span><span className="mt-1 block text-xs text-muted-foreground">{p.roomType} · {p.city}</span></span><span className="hidden text-right sm:block"><span className="block text-xs font-semibold">{p.progress}%</span><span className="mt-1 block text-[10px] uppercase tracking-wider text-muted-foreground">{p.status}</span></span><ArrowUpRight size={17} className="text-muted-foreground transition group-hover:text-primary" /></button>) : <EmptyState icon={BriefcaseBusiness} title="Your first room is waiting." copy="Start with a room concept or find a professional to shape the brief with you." action={<Link href="/ai-room-designer"><Button variant="coral" data-testid="button-empty-new-design">Design a room</Button></Link>} />}</div></section><section><h2 className="font-display text-4xl">Recent notes</h2><div className="mt-5 rounded-2xl border border-border bg-card p-6">{s?.recentActivity?.length ? <div className="space-y-5">{s.recentActivity.map((item, i) => <div key={item} className="flex gap-3 text-sm"><span className="mt-1 size-2 shrink-0 rounded-full bg-accent" /><span className="leading-6 text-muted-foreground">{item}</span></div>)}</div> : <EmptyState icon={Bell} title="All quiet here." copy="Your project updates will land in this space." />}</div></section></div></WorkspaceShell>;
}

function BusinessDashboard() {
  const dashboard = useGetBusinessDashboardSummary({ query: { queryKey: ['/api/business/dashboard/summary'] } }); const d = dashboard.data;
  const bars = d?.revenueSeries ?? []; const max = Math.max(...bars.map(b => b.value), 1);
  return <WorkspaceShell type="business"><div className="flex flex-wrap items-end justify-between gap-6"><div><SectionLabel>Business workspace</SectionLabel><h1 className="font-display text-5xl leading-none sm:text-6xl">Your studio,<br /><em>in motion.</em></h1></div><Button variant="outline" data-testid="button-business-settings"><Settings2 size={16} /> Workspace settings</Button></div>{dashboard.isError ? <div className="mt-8"><ErrorState message="Your business summary could not be loaded." /></div> : <><div className="mt-10 grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{[['Revenue', d ? money(d.revenue) : '—', 'This month'],['New leads', d?.newLeads ?? '—', 'Since Monday'],['Active projects', d?.activeProjects ?? '—', 'In delivery'],['Conversion', d ? `${d.conversionRate}%` : '—', 'Lead to client']].map(([l,v,sub], i) => <div key={String(l)} className={cn('rounded-2xl p-5', i === 0 ? 'bg-primary text-primary-foreground' : 'border border-border bg-card')}><div className="font-mono-app text-[10px] uppercase tracking-widest opacity-60">{l}</div><div className="mt-5 font-display text-4xl">{String(v)}</div><div className="mt-2 text-xs opacity-60">{sub}</div></div>)}</div><div className="mt-8 grid gap-6 lg:grid-cols-[1.15fr_.85fr]"><section className="rounded-2xl border border-border bg-card p-6 sm:p-8"><div className="flex items-start justify-between"><div><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">Revenue pulse</div><h2 className="mt-2 font-display text-3xl">A healthy direction.</h2></div><BarChart3 className="text-muted-foreground" size={20} /></div>{bars.length ? <div className="mt-10 flex h-48 items-end gap-2 sm:gap-4">{bars.map((bar, i) => <div key={bar.label} className="group flex flex-1 flex-col items-center gap-2"><div className="relative flex w-full flex-1 items-end"><div className={cn('w-full rounded-t-lg transition-all duration-500 group-hover:bg-accent', i === bars.length - 1 ? 'bg-accent' : 'bg-secondary')} style={{ height: `${Math.max(bar.value / max * 100, 5)}%` }} /></div><span className="font-mono-app text-[9px] text-muted-foreground">{bar.label}</span></div>)}</div> : <div className="mt-8"><EmptyState icon={BarChart3} title="Your graph starts here." copy="Revenue movement will appear once you have activity." /></div>}</section><section className="rounded-2xl bg-[#e8dfce] p-6 sm:p-8"><div className="font-mono-app text-[10px] uppercase tracking-widest text-primary/55">Lead pipeline</div><h2 className="mt-2 font-display text-3xl text-primary">Keep the good<br /><em>work moving.</em></h2><div className="mt-8 space-y-5">{d?.pipeline?.length ? d.pipeline.map(item => <div key={item.label}><div className="mb-2 flex justify-between text-xs text-primary"><span>{item.label}</span><strong>{item.value}</strong></div><div className="h-2 rounded-full bg-primary/10"><div className="h-full rounded-full" style={{ width: `${Math.min(item.value * 8, 100)}%`, background: item.color || '#eb7b5f' }} /></div></div>) : <EmptyState icon={Layers3} title="Pipeline is clear." copy="New enquiries will show up as they arrive." />}</div><div className="mt-10 border-t border-primary/15 pt-5 text-sm text-primary/70"><span className="font-semibold text-primary">{d?.rating ?? '—'} rating</span> from clients who notice the details.</div></section></div><div className="mt-8 rounded-2xl border border-border bg-card p-6"><div className="flex flex-wrap items-center justify-between gap-3"><h2 className="font-display text-3xl">Today’s focus</h2><span className="rounded-full bg-[#d5e1d7] px-3 py-1.5 text-xs font-semibold text-primary">All caught up</span></div><div className="mt-5 grid gap-3 md:grid-cols-3">{['Reply to 2 new enquiries','Review the Adebayo brief','Share a recent project'].map((x,i) => <button key={x} className="flex items-center gap-3 rounded-xl bg-muted p-4 text-left text-sm transition hover:bg-secondary" data-testid={`button-focus-${i}`}><span className="grid size-7 place-items-center rounded-full border border-primary/20 text-primary">{i + 1}</span>{x}<ArrowRight size={15} className="ml-auto text-muted-foreground" /></button>)}</div></div></>}</WorkspaceShell>;
}

function WorkspaceShell({ children, type }: { children: ReactNode; type: 'customer' | 'business' }) {
  const [mobile, setMobile] = useState(false); const items: Array<[string, string, ElementType]> = type === 'customer' ? [['Overview','/dashboard',LayoutDashboard],['Projects','/dashboard#projects',BriefcaseBusiness],['Saved professionals','/professionals',Heart],['AI room designer','/ai-room-designer',Sparkles]] : [['Overview','/business/dashboard',LayoutDashboard],['Leads','/business/dashboard#leads',Users],['Projects','/dashboard',BriefcaseBusiness],['Profile','/professionals',Compass]];
  return <PageShell><aside className={cn('fixed inset-y-0 left-0 z-50 w-[250px] bg-sidebar px-5 py-7 text-sidebar-foreground transition-transform duration-300 lg:translate-x-0', mobile ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center justify-between"><Mark light /><button className="rounded-full p-2 hover:bg-sidebar-accent lg:hidden" onClick={() => setMobile(false)} data-testid="button-close-sidebar"><X size={17} /></button></div><div className="mt-12 font-mono-app text-[9px] uppercase tracking-[.2em] text-sidebar-foreground/45">{type === 'customer' ? 'My space' : 'Nook Studio'}</div><nav className="mt-4 space-y-1">{items.map(([label, href, Icon]) => <Link key={String(label)} href={href} onClick={() => setMobile(false)} className="flex items-center gap-3 rounded-xl px-3 py-3 text-sm text-sidebar-foreground/70 transition hover:bg-sidebar-accent hover:text-sidebar-foreground" data-testid={`link-workspace-${String(label).toLowerCase().replaceAll(' ','-')}`}><Icon size={17} /> {label}</Link>)}</nav><div className="absolute bottom-7 left-5 right-5 rounded-2xl border border-sidebar-border bg-sidebar-accent p-4"><div className="flex items-center gap-2 text-xs font-semibold"><span className="size-2 rounded-full bg-accent" /> {type === 'customer' ? 'Amaka Okafor' : 'Nook Studio'}</div><p className="mt-2 text-[11px] leading-5 text-sidebar-foreground/50">{type === 'customer' ? 'Lagos, Nigeria' : 'Interior design · Lagos'}</p><Link href="/" className="mt-3 inline-flex text-[11px] text-accent" data-testid="link-workspace-exit">Back to marketplace <ArrowUpRight size={12} className="ml-1" /></Link></div></aside><div className="lg:pl-[250px]"><div className="flex h-[76px] items-center justify-between border-b border-border bg-background px-5 lg:px-10"><button onClick={() => setMobile(true)} className="rounded-full p-2 hover:bg-muted lg:hidden" data-testid="button-open-sidebar"><Menu /></button><div className="hidden text-sm text-muted-foreground lg:block">{type === 'customer' ? 'Tuesday, 08 October 2024' : 'Tuesday, 08 October 2024'}</div><div className="ml-auto flex items-center gap-2"><button className="grid size-10 place-items-center rounded-full hover:bg-muted" data-testid="button-notifications"><Bell size={18} /></button><span className="grid size-10 place-items-center rounded-full bg-accent text-xs font-bold text-accent-foreground">AO</span></div></div><main className="mx-auto max-w-[1320px] px-5 py-12 lg:px-10 lg:py-16">{children}</main></div></PageShell>;
}

function Admin() {
  const providers = useListProviders(undefined, { query: { queryKey: getListProvidersQueryKey() } }); const projects = useListProjects({ query: { queryKey: getListProjectsQueryKey() } });
  const adminMetrics: Array<{ label: string; value: string | number; icon: ElementType }> = [
    { label: 'Professionals', value: providers.data?.length ?? '—', icon: Users },
    { label: 'Customer projects', value: projects.data?.length ?? '—', icon: BriefcaseBusiness },
    { label: 'Trust checks', value: '100%', icon: ShieldCheck },
  ];
  return <WorkspaceShell type="business"><div className="flex items-end justify-between"><div><SectionLabel>Platform control</SectionLabel><h1 className="font-display text-6xl">Admin<br /><em>foundation.</em></h1></div><span className="rounded-full bg-[#d5e1d7] px-3 py-2 font-mono-app text-[10px] uppercase tracking-widest text-primary">System healthy</span></div><div className="mt-10 grid gap-3 md:grid-cols-3">{adminMetrics.map(({ label, value, icon: MetricIcon }) => <div key={label} className="rounded-2xl border border-border bg-card p-6"><MetricIcon size={19} className="text-accent" /><div className="mt-7 text-xs text-muted-foreground">{label}</div><div className="mt-2 font-display text-4xl">{String(value)}</div></div>)}</div><div className="mt-8 grid gap-6 lg:grid-cols-[1fr_.75fr]"><div className="rounded-2xl border border-border bg-card p-6"><div className="flex justify-between"><h2 className="font-display text-3xl">Recent professionals</h2><Button variant="quiet" data-testid="button-admin-export">Export <ArrowUpRight size={15} /></Button></div><div className="mt-5 divide-y divide-border">{providers.data?.slice(0,5).map(p => <div key={p.id} className="flex items-center gap-3 py-4"><span className="grid size-9 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{p.name.split(' ').map((x: string) => x[0]).slice(0,2).join('')}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{p.name}</p><p className="text-xs text-muted-foreground">{p.city} · {p.category}</p></div><span className="flex items-center gap-1 text-xs text-primary"><Check size={13} /> verified</span></div>)}</div></div><div className="rounded-2xl bg-primary p-6 text-primary-foreground"><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">Review queue</div><h2 className="mt-3 font-display text-4xl">Trust is<br /><em>the product.</em></h2><p className="mt-4 text-sm leading-6 text-primary-foreground/65">Every profile, project and payment touchpoint deserves a human eye as FurniConnect grows.</p><div className="mt-10 space-y-3"><div className="flex items-center justify-between rounded-xl bg-primary-foreground/10 p-3 text-sm"><span>Profiles awaiting review</span><strong>04</strong></div><div className="flex items-center justify-between rounded-xl bg-primary-foreground/10 p-3 text-sm"><span>Flagged content</span><strong>01</strong></div></div></div></div></WorkspaceShell>;
}

function AuthPage({ mode }: { mode: 'in' | 'up' }) { const [, setLocation] = useLocation(); const [submitted, setSubmitted] = useState(false); return <PageShell className="surface-grid"><div className="mx-auto grid min-h-[100dvh] max-w-[1200px] items-center gap-12 px-5 py-10 lg:grid-cols-2 lg:px-10"><div className="hidden rounded-[30px] bg-primary p-12 text-primary-foreground lg:block"><Mark light /><div className="mt-32 max-w-md"><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">A better way home</div><h1 className="mt-5 font-display text-7xl leading-[.88]">Your next<br /><em>room starts here.</em></h1><p className="mt-7 text-sm leading-7 text-primary-foreground/65">A trusted network for spaces with a point of view.</p></div><div className="mt-36 flex items-center gap-3 text-xs text-primary-foreground/50"><ShieldCheck size={16} className="text-accent" /> Verified professionals. Useful intelligence.</div></div><div className="mx-auto w-full max-w-[460px]"><Link href="/" className="mb-12 inline-flex lg:hidden" data-testid="link-auth-brand"><Mark /></Link><div className="font-mono-app text-[10px] uppercase tracking-widest text-accent">{mode === 'in' ? 'Welcome back' : 'Make yourself at home'}</div><h1 className="mt-4 font-display text-6xl leading-none">{mode === 'in' ? <>Good to<br /><em>see you.</em></> : <>Come on<br /><em>in.</em></>}</h1><p className="mt-5 text-sm leading-6 text-muted-foreground">{mode === 'in' ? 'Pick up where you left off.' : 'Join a more thoughtful way to make a space yours.'}</p>{submitted ? <div className="mt-10 rounded-2xl border border-primary/15 bg-[#d5e1d7] p-6"><Check className="text-primary" /><h2 className="mt-4 font-display text-3xl text-primary">You’re on your way.</h2><p className="mt-2 text-sm leading-6 text-primary/70">This demo workspace is ready. Take a look around.</p><Button className="mt-5" onClick={() => setLocation('/dashboard')} data-testid="button-auth-continue">Continue to workspace</Button></div> : <form className="mt-10 space-y-4" onSubmit={e => { e.preventDefault(); setSubmitted(true); }}><label className="block text-xs font-semibold">Email address<input required type="email" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none focus:border-primary" placeholder="you@example.com" data-testid="input-auth-email" /></label>{mode === 'up' && <label className="block text-xs font-semibold">Your name<input required className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none focus:border-primary" placeholder="Amaka Okafor" data-testid="input-auth-name" /></label>}<label className="block text-xs font-semibold">Password<input required type="password" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none focus:border-primary" placeholder="At least 8 characters" data-testid="input-auth-password" /></label><Button className="mt-3 w-full" variant="coral" type="submit" data-testid="button-auth-submit">{mode === 'in' ? 'Sign in' : 'Create account'} <ArrowRight size={16} /></Button><div className="flex items-center gap-3 py-3 text-xs text-muted-foreground"><span className="h-px flex-1 bg-border" /> or <span className="h-px flex-1 bg-border" /></div><Button className="w-full" variant="outline" type="button" data-testid="button-auth-google">Continue with Google</Button></form>}<p className="mt-8 text-center text-sm text-muted-foreground">{mode === 'in' ? 'New to FurniConnect?' : 'Already have an account?'} <Link href={mode === 'in' ? '/sign-up' : '/sign-in'} className="font-semibold text-primary underline-offset-4 hover:underline" data-testid="link-auth-switch">{mode === 'in' ? 'Create an account' : 'Sign in'}</Link></p></div></div></PageShell>; }

function Footer() { return <footer className="bg-primary px-5 py-12 text-primary-foreground lg:px-8"><div className="mx-auto flex max-w-[1320px] flex-wrap items-start justify-between gap-10"><div><Mark light /><p className="mt-5 max-w-xl text-sm leading-6 text-primary-foreground/65">BobTech Furniture connects skilled furniture makers, woodworkers, interior professionals, and luxury home décor experts with customers looking for quality, style, and craftsmanship across Africa.</p></div><div className="grid grid-cols-2 gap-x-14 gap-y-3 text-sm text-primary-foreground/65"><Link href="/professionals" data-testid="footer-link-professionals">Find professionals</Link><Link href="/ai-room-designer" data-testid="footer-link-ai">AI room designer</Link><Link href="/sign-up" data-testid="footer-link-join">Join the network</Link><Link href="/business/dashboard" data-testid="footer-link-business">For business</Link></div></div><div className="mx-auto mt-14 flex max-w-[1320px] justify-between border-t border-primary-foreground/15 pt-5 font-mono-app text-[9px] uppercase tracking-widest text-primary-foreground/40"><span>© 2025 BobTech Furnitures</span><span>Lagos · Nigeria</span></div></footer>; }

function Router() { return <ErrorBoundary resetKey={window.location.pathname}><Switch><Route path="/" component={Home} /><Route path="/ai-room-designer" component={AiDesigner} /><Route path="/professionals" component={Professionals} /><Route path="/professionals/:id" component={ProviderProfile} /><Route path="/dashboard" component={Dashboard} /><Route path="/business/dashboard" component={BusinessDashboard} /><Route path="/admin" component={Admin} /><Route path="/sign-in/*?" component={() => <AuthPage mode="in" />} /><Route path="/sign-up/*?" component={() => <AuthPage mode="up" />} /><Route component={NotFound} /></Switch></ErrorBoundary>; }

function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }

export default App;